window.DEMO_CONTEUDOS = [{"codigo": "SOP_TI_01", "titulo": "Configuracao de VPN Corporativa", "categoria": "TI e Acessos", "texto": "Para aceder a rede interna remotamente, o colaborador deve instalar o cliente OpenVPN a partir do portal interno. A autenticacao exige login corporativo e verificacao em duas etapas (2FA) via aplicacao Authenticator. Conexoes diretas sem MFA sao bloqueadas preventivamente pelo firewall.", "pergunta": "Como faco para aceder aos sistemas internos trabalhando a partir de casa?", "resposta": "Deve instalar o OpenVPN Client a partir do portal interno e autenticar-se utilizando as suas credenciais corporativas com verificacao em duas etapas (2FA)."}, {"codigo": "SOP_TI_02", "titulo": "Redefinicao de Senha de Dominio", "categoria": "TI e Acessos", "texto": "Caso o utilizador esqueca a senha de rede ou a conta seja bloqueada por tentativas incorretas, o desbloqueio deve ser efetuado no portal self-service de identidade ou solicitando reset temporario ao suporte pelo ramal 2100 mediante confirmacao do documento de identificacao.", "pergunta": "Como posso recuperar o acesso caso a minha senha de rede seja bloqueada?", "resposta": "Aceda ao portal de autoatendimento de identidade ou solicite o reset ao suporte pelo ramal 2100 confirmando os seus dados de identificacao."}, {"codigo": "SOP_TI_03", "titulo": "Acesso a Pastas Compartilhadas de Rede", "categoria": "TI e Acessos", "texto": "As permissoes em diretorios partilhados no servidor de ficheiros seguem o modelo RBAC. O colaborador deve solicitar acesso ao gestor da pasta via ticket no Service Desk, especificando o caminho completo e o perfil pretendido (leitura ou escrita).", "pergunta": "O que preciso de fazer para obter permissao de escrita numa pasta de rede?", "resposta": "Deve abrir um ticket no Service Desk informando o caminho do diretorio e anexando a aprovacao formal do gestor responsavel."}, {"codigo": "SOP_TI_04", "titulo": "Configuracao de Email Institucional no Telemovel", "categoria": "TI e Acessos", "texto": "O acesso ao webmail corporativo em dispositivos moveis requer a instalacao da aplicacao de gestao de dispositivos moveis (MDM). O dispositivo deve possuir bloqueio de ecra por PIN ou biometria e encriptacao de armazenamento ativa.", "pergunta": "Posso sincronizar o meu e-mail de trabalho no meu telemovel pessoal?", "resposta": "Sim, desde que instale a aplicacao de MDM corporativa e configure bloqueio de ecra por PIN ou biometria com encriptacao ativa."}, {"codigo": "SOP_TI_05", "titulo": "Criacao de Contas para Novos Colaboradores", "categoria": "TI e Acessos", "texto": "A criacao de novas contas corporativas deve ser solicitada pelo RH com 72 horas de antecedencia ao inicio das atividades. O processo provisiona automaticamente conta de Active Directory, e-mail institucional e licenca basica do pacote de produtividade.", "pergunta": "Qual e a antecedencia necessaria para requisitar os acessos de um novo funcionario?", "resposta": "O departamento de Recursos Humanos deve efetuar o pedido com pelo menos 72 horas de antecedencia atraves do Service Desk."}, {"codigo": "SOP_TI_06", "titulo": "Revogacao de Acessos em Desligamentos", "categoria": "TI e Acessos", "texto": "No processo de rescisao contratual, os acessos logicos do colaborador sao revogados de imediato apos comunicacao formal do RH. As credenciais sao desativadas e as sessoes ativas em aplicacoes cloud sao encerradas compulsoriamente.", "pergunta": "Quando sao cancelados os acessos de um funcionario demitido?", "resposta": "Os acessos sao revogados de forma imediata assim que o departamento de RH regista o desligamento no sistema de gestao."}, {"codigo": "SOP_TI_07", "titulo": "Solicitacao de Perfil de Administrador Local", "categoria": "TI e Acessos", "texto": "O acesso de administrador local em estacoes de trabalho e restrito a engenheiros de software e analistas de infraestrutura. A solicitacao requer aprovacao do CISO e justificativa tecnica, sendo a credencial rotativa com expiracao em 24 horas.", "pergunta": "Como posso solicitar privilegios de administrador temporario no meu computador?", "resposta": "Submeta um pedido no Service Desk com justificativa tecnica; apos aprovacao do CISO, sera concedida uma credencial valida por 24 horas."}, {"codigo": "SOP_TI_08", "titulo": "Configuracao de Chaves SSH Corporativas", "categoria": "TI e Acessos", "texto": "Chaves SSH para comunicacao com servidores Linux e repositorios Git devem utilizar algoritmo Ed25519 ou RSA de no minimo 4096 bits com passphrase obrigatoria. Chaves sem protecao por senha serao invalidadas pela equipa de seguranca.", "pergunta": "Quais sao as regras para cadastrar uma chave SSH nos servidores da empresa?", "resposta": "A chave deve ser gerada em Ed25519 ou RSA 4096 bits e conter obrigatoriamente uma passphrase de seguranca."}, {"codigo": "SOP_TI_09", "titulo": "Acesso a Ambientes de Cloud AWS e GCP", "categoria": "TI e Acessos", "texto": "O acesso as consolas de cloud computing e concedido via Single Sign-On (SSO) integrado com federacao de identidade. Nao sao permitidos utilizadores IAM locais sem MFA ativado nem chaves de acesso permanentes em maquinas de desenvolvimento.", "pergunta": "Como e efetuado o login nas plataformas cloud AWS ou Google Cloud?", "resposta": "O acesso e realizado exclusivamente atraves de Single Sign-On (SSO) federado com obrigatoriedade de segundo fator de autenticacao."}, {"codigo": "SOP_TI_10", "titulo": "Acesso de Prestadores de Servicos Externos", "categoria": "TI e Acessos", "texto": "Terceiros e consultores externos recebem contas temporarias identificadas pelo prefixo EXT, com validade maxima de 90 dias renovaveis mediante avaliacao do gestor de contrato e acesso restrito a VPN dedicada.", "pergunta": "Como funciona a concessao de acessos a consultores e prestadores terceirizados?", "resposta": "E criada uma conta temporaria prefixada com EXT, valida por ate 90 dias e vinculada a uma VPN com politicas restritivas."}, {"codigo": "SOP_TI_11", "titulo": "Abertura de Chamados e Matriz de SLA", "categoria": "Infraestrutura e Suporte", "texto": "Chamados abertos no Service Desk possuem quatro niveis de severidade: Critico (paragem total, SLA de 1 hora), Alto (impacto parcial em departamento, SLA de 4 horas), Medio (problema individual sem bloqueio total, SLA de 8 horas) e Baixo (duvidas e requisicoes, SLA de 24 horas uteis).", "pergunta": "Qual e o prazo de resposta para um problema que impede toda a equipa de trabalhar?", "resposta": "Incidentes criticos com paragem operacional tem SLA de atendimento de no maximo 1 hora."}, {"codigo": "SOP_TI_12", "titulo": "Manutencao Preventiva de Equipamentos", "categoria": "Infraestrutura e Suporte", "texto": "Os postos de trabalho passam por revisao preventiva a cada 12 meses, incluindo limpeza de componentes internos, atualizacao de firmware e testes de integridade de disco rigido e memoria RAM.", "pergunta": "Com que frequencia os computadores dos colaboradores passam por manutencao preventiva?", "resposta": "A revisao preventiva de computadores e portateis e realizada a cada 12 meses pela equipa de suporte local."}, {"codigo": "SOP_TI_13", "titulo": "Substituicao de Bateria de Portateis", "categoria": "Infraestrutura e Suporte", "texto": "Portateis que apresentem autonomia inferior a 60 minutos ou com avisos de degradacao de celulas no sistema operacional devem ser encaminhados ao suporte para troca do componente em ate 48 horas.", "pergunta": "O que fazer se a bateria do meu portatil estiver a durar menos de uma hora?", "resposta": "Abra um chamado no Service Desk para avaliacao tecnica e substituicao da bateria no prazo de ate 48 horas."}, {"codigo": "SOP_TI_14", "titulo": "Configuracao de Impressoras de Rede", "categoria": "Infraestrutura e Suporte", "texto": "As impressoras departamentais sao mapeadas automaticamente pelo script de logon da rede. Caso a impressora nao surja na lista de dispositivos, o colaborador deve adicionar o dispositivo informando o IP institucional da impressora do setor.", "pergunta": "Como posso mapear a impressora do meu andar se ela nao aparecer automaticamente?", "resposta": "Aceda as configuracoes de impressao do sistema e adicione a impressora utilizando o endereco IP fornecido pela equipa de suporte."}, {"codigo": "SOP_TI_15", "titulo": "Instalacao de Softwares Homologados", "categoria": "Infraestrutura e Suporte", "texto": "A instalacao de softwares deve ser feita exclusivamente atraves da Software Center da empresa. A utilizacao de instaladores baixados da internet sem aprovacao previa do setor de TI e bloqueada pelo sistema de politicas locais.", "pergunta": "Como instalo ferramentas de trabalho como navegadores ou visualizadores de PDF?", "resposta": "Utilize o catalogo corporativo Software Center instalado no computador, onde estao disponiveis os programas homologados."}, {"codigo": "SOP_TI_16", "titulo": "Emprestimo de Equipamentos em Viagens", "categoria": "Infraestrutura e Suporte", "texto": "Colaboradores em viagem a trabalho podem requisitar adaptadores de video, modems 4G/5G portateis e extensoes atraves de solicitacao com 5 dias uteis de antecedencia ao suporte tecnico.", "pergunta": "Como solicitar acessorios de TI para uma viagem de trabalho?", "resposta": "Abra um ticket com no minimo 5 dias uteis de antecedencia detalhando as datas da viagem e os acessorios necessarios."}, {"codigo": "SOP_TI_17", "titulo": "Politica de Troca e Upgrade de Maquinas", "categoria": "Infraestrutura e Suporte", "texto": "A substituicao tecnologica de portateis ocorre a cada 36 meses para perfis operacionais e a cada 24 meses para cargos tecnicos de alta demanda computacional (como desenvolvedores e cientistas de dados).", "pergunta": "Qual e o ciclo de substituicao dos computadores corporativos?", "resposta": "A renovacao de parque ocorre a cada 36 meses para utilizadores comuns e 24 meses para funcoes de engenharia e dados."}, {"codigo": "SOP_TI_18", "titulo": "Procedimento para Recuperacao de Backups", "categoria": "Infraestrutura e Suporte", "texto": "Backups de ficheiros armazenados no OneDrive corporativo podem ser recuperados pelo proprio utilizador pelo historico de versoes de ate 30 dias. Para servidores locais, a solicitacao deve ser enviada ao setor de infraestrutura.", "pergunta": "Como recuperar uma versao anterior de um documento que foi apagado acidentalmente?", "resposta": "Ficheiros na nuvem institucional podem ser recuperados pelo historico de versoes do OneDrive em ate 30 dias."}, {"codigo": "SOP_TI_19", "titulo": "Problemas de Conectividade Wi-Fi no Escritorio", "categoria": "Infraestrutura e Suporte", "texto": "A rede sem fios Corporativa-Secure destina-se a maquinas institucionais com certificado digital instalado. Visitantes e telemoveis pessoais devem utilizar exclusivamente a rede Corporativa-Visitantes mediante registo temporario.", "pergunta": "Qual rede Wi-Fi devo conectar no meu computador de trabalho dentro da empresa?", "resposta": "Deve ligar-se a rede Corporativa-Secure, que utiliza autenticacao automatica via certificado corporativo."}, {"codigo": "SOP_TI_20", "titulo": "Instalacao de Ambientes de Desenvolvimento Python", "categoria": "Infraestrutura e Suporte", "texto": "Desenvolvedores devem utilizar instaladores de Python gerenciados via Miniforge ou pyenv, isolando dependencias em ambientes virtuais (venv). E vedada a instalacao de bibliotecas no ambiente root do sistema.", "pergunta": "Qual e a recomendacao para criar ambientes de programacao Python no projeto?", "resposta": "Utilize pyenv ou Miniforge para gerir as versoes e crie sempre ambientes virtuais dedicados (venv) para cada projeto."}, {"codigo": "SOP_TI_21", "titulo": "Descarte Seguro de Fitas e Discos", "categoria": "Infraestrutura e Suporte", "texto": "Dispositivos de armazenamento magnetico ou solido (HDs e SSDs) obsoletos passam por desmagnetizacao e destruicao fisica certificada, sendo emitido um laudo de descarte seguro compativel com a norma ISO 27001.", "pergunta": "Como e realizado o descarte de discos rigidos antigos na organizacao?", "resposta": "Os discos passam por desmagnetizacao e trituracao fisica com emissao de certificado de destruicao segura."}, {"codigo": "SOP_TI_22", "titulo": "Monitorizacao de Servidores e Servicos", "categoria": "Infraestrutura e Suporte", "texto": "Os servidores sao monitorizados 24 horas por dia por sistemas de telemetria. Incidentes em servicos de producao geram alertas automaticos nos canais de operacoes via PagerDuty e Teams.", "pergunta": "Quem e notificado quando um servico de producao apresenta indisponibilidade?", "resposta": "A equipa de operacoes recebe alertas automaticos em tempo real via PagerDuty e canais criticos de comunicacao."}, {"codigo": "SOP_TI_23", "titulo": "Configuracao de Proxy e Certificado Raiz", "categoria": "Infraestrutura e Suporte", "texto": "O tráfego de rede corporativo passa por proxy seguro. Todas as estacoes devem possuir o certificado raiz da autoridade certificadora interna instalado no keystore do sistema operacional e de ferramentas como Git e Docker.", "pergunta": "Por que motivo recebo erro de certificado SSL ao rodar comandos no terminal?", "resposta": "E necessario certificar-se de que a autoridade certificadora interna esta instalada no keystore da ferramenta ou configurar o proxy corporativo."}, {"codigo": "SOP_TI_24", "titulo": "Uso de Perifericos e Teclados Personalizados", "categoria": "Infraestrutura e Suporte", "texto": "A conexao de teclados, ratos e fones USB homologados e permitida. Perifericos com memoria de armazenamento flash interna ou capacidade de programacao de macros via firmware requerem analise da equipa de seguranca.", "pergunta": "Posso ligar o meu teclado mecanico pessoal com memoria interna ao computador de trabalho?", "resposta": "Perifericos que possuam memoria interna flash ou macros necessitam de autorizacao previa da seguranca da informacao."}, {"codigo": "SOP_TI_25", "titulo": "Acesso ao Banco de Dados de Desenvolvimento", "categoria": "Infraestrutura e Suporte", "texto": "Conexoes a bases de dados de desenvolvimento exigem cliente VPN ativo e credenciais individuais com principio do menor privilegio. Nao e permitido o uso compartilhado de credenciais genericas como root ou admin.", "pergunta": "Como acedo a base de dados do ambiente de desenvolvimento?", "resposta": "Conecte-se a VPN corporativa e utilize as suas credenciais individuais fornecidas com permissoes restritas a sua atividade."}, {"codigo": "SOP_SEC_01", "titulo": "Politica Geral de Senhas Corporativas", "categoria": "Seguranca e LGPD", "texto": "As senhas corporativas devem conter no minimo 12 caracteres com letras maiusculas, minusculas, numeros e simbolos especiais. A expiracao ocorre a cada 60 dias, sendo proibida a repeticao das ultimas 10 senhas utilizadas.", "pergunta": "Quais as caracteristicas obrigatorias da senha da minha conta de utilizador?", "resposta": "Deve ter no minimo 12 caracteres, incluir combinacao de maiusculas, minusculas, numeros e simbolos, e ser renovada a cada 60 dias."}, {"codigo": "SOP_SEC_02", "titulo": "Classificacao da Informacao e Dados Confidenciais", "categoria": "Seguranca e LGPD", "texto": "Toda a documentacao interna deve ser rotulada em quatro niveis: Publica, Interna, Confidencial ou Estritamente Confidencial. Documentos com dados estrategicos de clientes sao classificados como Estritamente Confidenciais e requerem encriptacao em transito e em repouso.", "pergunta": "Como devo rotular um relatorio financeiro ou lista de clientes antes de partilhar?", "resposta": "Classifique-o como Estritamente Confidencial e certifique-se de que o ficheiro se encontra encriptado antes de qualquer partilha."}, {"codigo": "SOP_SEC_03", "titulo": "Notificacao de Fugas de Dados Pessoais (LGPD)", "categoria": "Seguranca e LGPD", "texto": "Qualquer colaboracao ou colaborador que suspeite de violacao de dados pessoais (PII) deve reportar o fato em ate 2 horas ao DPO atraves do e-mail dpo-privacidade@empresa.com.br ou pelo ramal 9901 para cumprimento do artigo 48 da LGPD.", "pergunta": "A quem devo comunicar caso constate o envio indevido de uma folha com dados pessoais?", "resposta": "Deve notificar imediatamente o Encarregado de Dados (DPO) pelo e-mail dpo-privacidade@empresa.com.br ou ramal 9901 em ate 2 horas."}, {"codigo": "SOP_SEC_04", "titulo": "Bloqueio de Portas USB e Unidades Amoviveis", "categoria": "Seguranca e LGPD", "texto": "A utilizacao de pens USB, discos rigidos externos e cartoes de memoria e bloqueada por omissao nos computadores corporativos. Excecoes para operacoes tecnicas devem ser formalizadas via chamado e autorizadas pela diretoria de TI.", "pergunta": "Por que motivo o meu computador nao reconhece a pen USB que conectei?", "resposta": "As portas USB para armazenamento estao bloqueadas por diretiva de seguranca para evitar fugas de dados e infecoes por malware."}, {"codigo": "SOP_SEC_05", "titulo": "Uso Seguro de Inteligencia Artificial Generativa", "categoria": "Seguranca e LGPD", "texto": "E proibido enviar dados pessoais de clientes, contratos confidenciais ou segredos industriais para ferramentas de IA abertas na internet. O uso deve ocorrer unicamente pela plataforma homologada OutGPT Enterprise.", "pergunta": "Posso colar excertos de contratos confidenciais no ChatGPT web gratuito?", "resposta": "Nao. E expressamente proibido enviar informacoes corporativas ou confidenciais a ferramentas externas abertas."}, {"codigo": "SOP_SEC_06", "titulo": "Bloqueio Automatico de Ecra e Politica de Mesa Limpa", "categoria": "Seguranca e LGPD", "texto": "O tempo limite de inatividade para bloqueio automatico de ecra e de 5 minutos. Colaboradores devem manter as mesas limpas de documentos fisicos que contenham dados pessoais ou senhas anotadas em post-its.", "pergunta": "O que e exigido quanto a seguranca fisica do meu posto de trabalho?", "resposta": "Deve bloquear o ecra ao ausentar-se (bloqueio automatico em 5 min) e nao deixar papeis com informacoes confidenciais na mesa."}, {"codigo": "SOP_SEC_07", "titulo": "Prevencao de Ataques de Phishing e Engenharia Social", "categoria": "Seguranca e LGPD", "texto": "E-mails suspeitos contendo links externos, anexos executaveis ou remetentes clonados devem ser reportados pelo botao Reportar Phishing no Outlook. Nunca insira credenciais de acesso em paginas externas nao validadas.", "pergunta": "O que fazer ao receber um e-mail com cobranca suspeita pedindo para clicar num link?", "resposta": "Nao clique no link e acione o botao de alerta Reportar Phishing no cliente de e-mail institucional para analise da seguranca."}, {"codigo": "SOP_SEC_08", "titulo": "Anonimizacao e Mascaramento de PII em Projetos", "categoria": "Seguranca e LGPD", "texto": "Bases de dados usadas para desenvolvimento, teste e modelos de machine learning devem passar por processo previo de anonimizacao ou pseudonimizacao de identificadores pessoais (como CPF, nome completo e telefone).", "pergunta": "Podemos utilizar a base de dados real de clientes para treinar novos modelos de machine learning?", "resposta": "Nao, a base de testes deve passar obrigatoriamente por mascaramento de dados sensiveis e anonimizacao antes de ser utilizada."}, {"codigo": "SOP_SEC_09", "titulo": "Controlo de Acesso Baseado em Funcoes (RBAC)", "categoria": "Seguranca e LGPD", "texto": "A concessao de privilegios em sistemas corporativos baseia-se no principio do menor privilegio e atribuicao por grupo de funcao (RBAC). Cada alteracao de cargo dispara a revisao automatica dos acessos herdados.", "pergunta": "Como sao definidas as permissoes de acesso de cada colaborador aos sistemas?", "resposta": "Sao definidas com base no perfil da funcao (RBAC), concedendo unicamente as permissoes essenciais a execucao do cargo."}, {"codigo": "SOP_SEC_10", "titulo": "Registo e Auditoria de Logs de Acesso", "categoria": "Seguranca e LGPD", "texto": "Todas as consultas, downloads e alteracoes em dados confidenciais sao registados em logs inalteraveis com identificacao de IP, timestamp e identidade do utilizador, armazenados por 5 anos para efeitos de auditoria e conformidade.", "pergunta": "As acoes realizadas dentro das aplicacoes internas sao monitorizadas?", "resposta": "Sim, todas as interacoes e consultas a documentos confidenciais sao auditadas e registadas em logs inalteraveis."}, {"codigo": "SOP_SEC_11", "titulo": "Gestao de Vulnerabilidades e Aplicacao de Patches", "categoria": "Seguranca e LGPD", "texto": "Atualizacoes de seguranca de criticidade alta ou critica devem ser aplicadas nos sistemas operacionais e servidores em no maximo 14 dias corridos apos a publicacao do fabricante.", "pergunta": "Em quanto tempo uma atualizacao critica do Windows deve ser instalada no computador?", "resposta": "Patches criticos devem ser instalados no prazo maximo de 14 dias apos serem disponibilizados pelo fabricante."}, {"codigo": "SOP_SEC_12", "titulo": "Destruicao Segura de Documentos em Papel", "categoria": "Seguranca e LGPD", "texto": "Documentos impressos contendo dados pessoais ou demonstracoes financeiras devem ser descartados exclusivamente nos coletores trituradores seguros identificados no setor, sendo proibido o descarte em lixo comum.", "pergunta": "Onde devo deitar fora folhas impressas com dados de faturas ou colaboradores?", "resposta": "Devem ser colocadas nos coletores trituradores de seguranca existentes nos andares, nunca em recipientes de lixo comum."}, {"codigo": "SOP_SEC_13", "titulo": "Uso de Redes Wi-Fi Publicas em Viagens", "categoria": "Seguranca e LGPD", "texto": "Ao trabalhar em aeroportos, hoteis ou cafeterias, e compulsorio o uso da VPN corporativa imediatamente apos a ligacao a rede sem fios, evitando a intercecao de trafego nao encriptado por agentes maliciosos.", "pergunta": "E seguro aceder aos ficheiros da empresa atraves do Wi-Fi de um hotel?", "resposta": "Apenas se ativar a VPN institucional antes de iniciar qualquer atividade ou consulta de dados corporativos."}, {"codigo": "SOP_SEC_14", "titulo": "Politica de Consciencializacao e Treinos de Seguranca", "categoria": "Seguranca e LGPD", "texto": "Todos os funcionarios devem concluir os modulos anuais de formacao em ciberseguranca e privacidade na plataforma de aprendizagem interna, com aproveitamento minimo de 80% nos testes de fixacao.", "pergunta": "Qual e a frequencia e a nota minima dos treinamentos de ciberseguranca?", "resposta": "O curso deve ser realizado anualmente na plataforma interna e requer nota minima de aprovacao de 80%."}, {"codigo": "SOP_SEC_15", "titulo": "Revogacao de Consentimento de Titulares de Dados", "categoria": "Seguranca e LGPD", "texto": "Quando um cliente solicitar a eliminacao dos seus dados pessoais com base na LGPD, o setor de Compliance deve processar a requisicao nos sistemas transacionais e de arquivo no prazo legal de ate 15 dias.", "pergunta": "Qual o prazo para atender a solicitacao de um cliente que deseja apagar os seus dados cadastrais?", "resposta": "A solicitacao de eliminacao com base na LGPD deve ser concluida nos sistemas no prazo maximo de 15 dias."}, {"codigo": "SOP_SEC_16", "titulo": "Procedimento para Gestao de Chaves Criptograficas", "categoria": "Seguranca e LGPD", "texto": "Chaves de encriptacao de bases de dados devem ser armazenadas em servicos dedicados de Key Management Service (KMS), com rotacao anual automatica e acesso restrito a administradores de seguranca.", "pergunta": "Como e garantida a protecao das chaves criptograficas da empresa?", "resposta": "As chaves sao guardadas em modulos KMS com renovacao automatica a cada 12 meses e acesso restrito."}, {"codigo": "SOP_SEC_17", "titulo": "Termo de Confidencialidade e Nao Divulgacao (NDA)", "categoria": "Seguranca e LGPD", "texto": "Todos os colaboradores assinam o Acordo de Confidencialidade no momento da admissao, comprometendo-se a manter segredo sobre tecnologias, processos e dados operacionais durante e apos o vinculo empregaticio.", "pergunta": "O compromisso de sigilo corporativo continua a valer apos o encerramento do contrato?", "resposta": "Sim, o termo de confidencialidade (NDA) permanece em vigor mesmo apos o desligamento do colaborador."}, {"codigo": "SOP_SEC_18", "titulo": "Identificacao Visual com Cracha nas Dependencias", "categoria": "Seguranca e LGPD", "texto": "E obrigatorio o uso visivel do cracha corporativo nas instalacoes da organizacao. A entrada de pessoas sem cracha de funcionario ou visitante e expressamente vedada pela portaria.", "pergunta": "Preciso de usar o cracha no pescoco durante todo o dia no escritorio?", "resposta": "Sim, o cracha institucional deve permanecer visivel durante toda a permanencia nas instalacoes da empresa."}, {"codigo": "SOP_SEC_19", "titulo": "Denuncia de Praticas Ilicitas no Canal de Etica", "categoria": "Seguranca e LGPD", "texto": "Indicios de fraude, corrupcao, discriminacao ou vazamento intencional de segredos corporativos devem ser registados no Canal de Etica independente pelo telefone 0800-770-0011 ou pelo portal online, com garantia de sigilo e protecao ao denunciante.", "pergunta": "Como posso reportar um desvio etico ou fraude de forma totalmente anonima?", "resposta": "Utilize o Canal de Etica corporativo atraves do telefone 0800-770-0011 ou formulario seguro online."}, {"codigo": "SOP_SEC_20", "titulo": "Avaliacao de Fornecedores e Seguranca de Terceiros", "categoria": "Seguranca e LGPD", "texto": "Novos softwares e fornecedores de servicos cloud devem passar por analise de risco do departamento de Seguranca da Informacao antes da assinatura contratual, preenchendo questionario de conformidade tecnica.", "pergunta": "O departamento de compras pode contratar uma ferramenta de software sem aval da TI?", "resposta": "Nao, qualquer contratacao de software ou servico em nuvem precisa de analise previa de seguranca e conformidade."}, {"codigo": "SOP_RH_01", "titulo": "Registo de Ponto Eletronico e Tolerancias", "categoria": "Recursos Humanos e Carreira", "texto": "O registo de ponto deve ser realizado digitalmente na aplicacao PontoWeb no inicio, intervalo de refeicao (minimo 1 hora) e final da jornada. Existe tolerancia maxima legal de 10 minutos diarios para eventuais variacoes.", "pergunta": "O que acontece se me esquecer de bater o ponto na saida do almoco?", "resposta": "Deve solicitar a correcao e inclusao de justificativa no sistema PontoWeb com a anuencia do seu gestor direto."}, {"codigo": "SOP_RH_02", "titulo": "Compensacao de Horas e Banco de Horas", "categoria": "Recursos Humanos e Carreira", "texto": "Horas extraordinarias executadas mediante aprovacao previa acumulam-se no banco de horas. A compensacao deve ocorrer dentro do periodo de 6 meses, sendo o saldo remanescente liquidado na folha de pagamento seguinte.", "pergunta": "Qual o prazo maximo para utilizar as horas acumuladas no meu banco de horas?", "resposta": "As horas devem ser compensadas em ate 6 meses; caso nao sejam gozadas, serao pagas em folha salarial."}, {"codigo": "SOP_RH_03", "titulo": "Aquisicao e Agendamento de Ferias", "categoria": "Recursos Humanos e Carreira", "texto": "O colaborador adquire direito a 30 dias de ferias apos cada periodo de 12 meses de trabalho. O agendamento pode ser fracionado em ate 3 periodos, devendo ser submetido com pelo menos 45 dias de antecedencia no portal de RH.", "pergunta": "Com quanto tempo de antecedencia devo marcar o meu periodo de ferias?", "resposta": "O agendamento deve ser efetuado no portal de RH com pelo menos 45 dias de antecedencia a data de inicio."}, {"codigo": "SOP_RH_04", "titulo": "Envio de Atestados Medicos e Prazos", "categoria": "Recursos Humanos e Carreira", "texto": "Atestados de incapacidade laboral devem ser digitalizados e enviados pelo aplicativo de RH em ate 48 horas apos a emissao, contendo assinatura do medico, CRM e indicacao do numero de dias de afastamento recomendados.", "pergunta": "Qual o prazo para entregar um atestado medico de afastamento?", "resposta": "O atestado deve ser enviado atraves do portal de RH no prazo maximo de 48 horas a contar da sua emissao."}, {"codigo": "SOP_RH_05", "titulo": "Plano de Saude e Inclusao de Dependentes", "categoria": "Recursos Humanos e Carreira", "texto": "Novos colaboradores tem 30 dias apos a admissao para incluir conjuges e dependentes legais ate 21 anos (ou 24 anos se universitarios) no plano de saude sem cumprimento de periodos de carencia.", "pergunta": "Ate que idade os filhos podem ser dependentes no plano de saude corporativo?", "resposta": "Filhos sao elegiveis ate os 21 anos, ou ate os 24 anos caso estejam regularmente matriculados em curso superior."}, {"codigo": "SOP_RH_06", "titulo": "Reembolso de Despesas com Alimentacao e Viagem", "categoria": "Recursos Humanos e Carreira", "texto": "Despesas de alimentacao e deslocamento em servico devem ser submetidas no modulo corporativo de reembolsos anexando os comprovantes e notas fiscais com discriminacao de itens em ate 15 dias corridos.", "pergunta": "Qual o prazo para solicitar o reembolso de uma despesa incorrida numa viagem a servico?", "resposta": "Os comprovantes fiscais devem ser submetidos no sistema no prazo maximo de 15 dias corridos apos a despesa."}, {"codigo": "SOP_RH_07", "titulo": "Subsidio Educacional e Incentivo a Certificacoes", "categoria": "Recursos Humanos e Carreira", "texto": "A organizacao compartilha ate 70% dos custos de cursos superiores e pos-graduacoes alinhadas a funcao, e reembolsa 100% de certificacoes tecnicas homologadas mediante apresentacao do certificado de aprovacao.", "pergunta": "Como funciona a ajuda de custo da empresa para realizacao de certificacoes tecnicas?", "resposta": "A organizacao reembolsa integralmente o exame de certificacao tecnica desde que haja aprovacao e alinhamento com a area."}, {"codigo": "SOP_RH_08", "titulo": "Avaliacao de Desempenho e Feedback Continuo", "categoria": "Recursos Humanos e Carreira", "texto": "Os ciclos formais de avaliacao de desempenho 360 graus ocorrem semestralmente em junho e dezembro, complementados por alinhamentos mensais de feedback (1-on-1) com a respetiva lideranca direta.", "pergunta": "Quando acontecem as avaliacoes de desempenho oficiais da empresa?", "resposta": "As avaliacoes formais sao realizadas semestralmente nos meses de junho e dezembro, com feedbacks mensais regulares."}, {"codigo": "SOP_RH_09", "titulo": "Programa de Mobilidade Interna e Vagas", "categoria": "Recursos Humanos e Carreira", "texto": "Colaboradores com mais de 6 meses no cargo atual e historico positivo de avaliacao podem candidatar-se a vagas internas abertas antes da publicacao em canais de recrutamento externo.", "pergunta": "Quanto tempo preciso de estar na funcao atual para concorrer a uma vaga interna?", "resposta": "E necessario um tempo minimo de permanencia de 6 meses na posicao atual e boa avaliacao funcional."}, {"codigo": "SOP_RH_10", "titulo": "Licenca Maternidade e Paternidade Estendida", "categoria": "Recursos Humanos e Carreira", "texto": "Por fazer parte do programa Empresa Cidada, a empresa concede licenca maternidade estendida de 180 dias e licenca paternidade de 20 dias corridos, garantindo estabilidade salarial plena.", "pergunta": "Qual a duracao da licenca maternidade e paternidade concedida pela organizacao?", "resposta": "Sao concedidos 180 dias de licenca maternidade e 20 dias corridos de licenca paternidade remunerada."}, {"codigo": "SOP_RH_11", "titulo": "Auxilio Creche para Colaboradores", "categoria": "Recursos Humanos e Carreira", "texto": "Colaboradoras e colaboradores com guarda judicial de filhos recebem auxilio creche mensal ate a crianca completar 5 anos de idade, mediante apresentacao anual de comprovante de matricula escolar.", "pergunta": "Ate qual idade e pago o subsidio de auxilio creche?", "resposta": "O auxilio e concedido mensalmente ate que a crianca complete 5 anos de idade mediante apresentacao de comprovante."}, {"codigo": "SOP_RH_12", "titulo": "Politica de Trabalho Hibrido e Ajuda de Custo", "categoria": "Recursos Humanos e Carreira", "texto": "O modelo hibrido estabelece 2 dias presenciais no escritorio e 3 dias em regime de home office semanais, com concessao de ajuda de custo mensal fixa destinada a subsidiar despesas de energia e internet.", "pergunta": "Quantos dias presenciais sao obrigatorios no regime hibrido de trabalho?", "resposta": "A politica define a presenca de 2 dias por semana no escritorio e 3 dias em trabalho remoto."}, {"codigo": "SOP_RH_13", "titulo": "Programa de Indicacao de Talentos (Bounties)", "categoria": "Recursos Humanos e Carreira", "texto": "Colaboradores que indicarem profissionais contratados para posicoes estrategicas de TI e dados recebem um bonus de indicacao pago no terceiro mes subsequente a admissao do indicado.", "pergunta": "Como funciona a bonificacao por indicacao de candidatos para vagas abertas?", "resposta": "Apos a contratacao e permanencia do profissional indicado por 90 dias, o colaborador recebe o bonus de premiacao."}, {"codigo": "SOP_RH_14", "titulo": "Vestimenta e Codigo de Aparencia Corporativo", "categoria": "Recursos Humanos e Carreira", "texto": "A empresa adota estilo casual no dia a dia, sendo permitido o uso de calcas jeans e sapatilhas. Em reunioes com clientes externos e audiencias institucionais, e recomendado traje esporte fino ou formal.", "pergunta": "Existe um codigo formal e rigoroso de vestimenta para o escritorio?", "resposta": "O codigo diario e casual, reservando-se vestimenta formal ou esporte fino apenas para reunioes com clientes externos."}, {"codigo": "SOP_RH_15", "titulo": "Politica contra Assedio e Discriminacao", "categoria": "Recursos Humanos e Carreira", "texto": "A organizacao adota tolerancia zero contra qualquer forma de assedio moral, sexual ou manifestacao discriminatoria de genero, raca ou religiao, com penalidades que incluem rescisao por justa causa.", "pergunta": "Qual e a postura da empresa diante de casos comprovados de assedio moral ou sexual?", "resposta": "A empresa adota tolerancia zero absoluta, aplicando medidas disciplinares rigorosas que chegam a demissao por justa causa."}, {"codigo": "SOP_RH_16", "titulo": "Seguro de Vida em Grupo e Coberturas", "categoria": "Recursos Humanos e Carreira", "texto": "O seguro de vida oferecido sem custo aos funcionarios cobre morte natural, acidental e invalidez permanente, assegurando indenizacao correspondente a 24 vezes o salario base contratual.", "pergunta": "Qual e a cobertura do seguro de vida fornecido pela empresa?", "resposta": "A apolice cobre acidentes, falecimento e invalidez permanente no montante correspondente a 24 vezes o salario base."}, {"codigo": "SOP_RH_17", "titulo": "Adiantamento do Decimo Terceiro Salario", "categoria": "Recursos Humanos e Carreira", "texto": "O adiantamento da primeira parcela do decimo terceiro salario pode ser requisitado juntamente com o gozo de ferias anuais caso o colaborador formalize o pedido por escrito ate 31 de janeiro do respetivo ano.", "pergunta": "Como posso solicitar a primeira parcela do meu 13º salario adiantada nas ferias?", "resposta": "O pedido deve ser protocolado por escrito no RH ate ao dia 31 de janeiro do ano em exercicio."}, {"codigo": "SOP_RH_18", "titulo": "Programa de Apoio Psicologico e Saude Mental", "categoria": "Recursos Humanos e Carreira", "texto": "Colaboradores e dependentes tem acesso gratuito e ilimitado a servico de telepsicologia e suporte juridico e financeiro 24 horas por dia por meio da plataforma externa VivaBem.", "pergunta": "Como posso aceder a consultas de apoio psicologico oferecidas pela organizacao?", "resposta": "O servico de orientacao e telepsicologia pode ser acionado gratuitamente a qualquer hora via plataforma VivaBem."}, {"codigo": "SOP_RH_19", "titulo": "Emprestimo Consignado e Parcerias Bancarias", "categoria": "Recursos Humanos e Carreira", "texto": "Funcionarios com mais de um ano de contrato podem contrair emprestimos consignados com desconto em folha atraves dos bancos conveniados, com limite de comprometimento maximo de 30% da renda liquida.", "pergunta": "Qual e a margem consignavel maxima permitida para emprestimo com desconto em folha?", "resposta": "A legislacao e a politica interna autorizam comprometer no maximo 30% da renda liquida salarial."}, {"codigo": "SOP_RH_20", "titulo": "Regras para Uso de Redes Sociais e Marca", "categoria": "Recursos Humanos e Carreira", "texto": "E vedado expressar posicoes oficiais em nome da empresa nas redes sociais pessoais sem aprovacao da assessoria de imprensa. O uso do logotipo e marcas registradas obedece ao manual de identidade institucional.", "pergunta": "Posso falar publicamente em nome da empresa no meu perfil do LinkedIn?", "resposta": "Nao. Pronunciamentos oficiais e uso institucional da marca requerem avalizacao expressa da assessoria de comunicacao."}, {"codigo": "SOP_RH_21", "titulo": "Dia de Folga de Aniversario (Birthday Off)", "categoria": "Recursos Humanos e Carreira", "texto": "No mes de aniversario, o colaborador tem direito a um dia de folga remunerada a sua escolha, devendo acordar a data com a sua chefia direta com 10 dias de antecedencia minima.", "pergunta": "Como funciona a folga remunerada no dia do meu aniversario?", "resposta": "O dia de descanso pode ser gozado no mes natalicio mediante alinhamento previo de 10 dias com o seu gestor."}, {"codigo": "SOP_RH_22", "titulo": "Ginasio e Programa de Bem-Estar Fisico", "categoria": "Recursos Humanos e Carreira", "texto": "A empresa oferece parceria com a plataforma Gympass/TotalPass com mensalidades subsidiadas, dando acesso a redes de academias e estudos de treino em todo o territorio nacional.", "pergunta": "Como me inscrevo no plano subsidiado de academias e ginasios?", "resposta": "Descarregue a aplicacao do parceiro de bem-estar e registe-se utilizando o seu e-mail funcional e matricula corporativa."}, {"codigo": "SOP_RH_23", "titulo": "Premio de Retencao e Participacao nos Lucros (PLR)", "categoria": "Recursos Humanos e Carreira", "texto": "O pagamento da Participacao nos Lucros e Resultados e efetuado anualmente mediante o atingimento das metas corporativas globais e os indicadores individuais acordados no inicio do ciclo.", "pergunta": "Quais fatores determinam o valor pago na PLR anual?", "resposta": "O montante depende do cumprimento das metas globais da empresa associado ao desempenho individual obtido na avaliacao."}, {"codigo": "SOP_RH_24", "titulo": "Procedimento para Alteracao Cadastral de Conta", "categoria": "Recursos Humanos e Carreira", "texto": "Alteracoes de domicilio bancario para pagamento do salario devem ser solicitadas no portal de RH anexando extrato de comprovativo de titularidade ate o dia 10 do mes corrente.", "pergunta": "Qual o dia limite para mudar a conta bancaria onde recebo o meu ordenado?", "resposta": "A solicitacao e o comprovativo bancario devem ser enviados ate ao dia 10 para entrar em vigor na folha do mes."}, {"codigo": "SOP_RH_25", "titulo": "Canal de Comunicacao Interna e Ouvidoria", "categoria": "Recursos Humanos e Carreira", "texto": "Questoes e sugestoes nao resolvidas pelo gestor imediato podem ser encaminhadas diretamente a Ouvidoria Interna de RH, com garantia de retorno formalizado em ate 5 dias uteis.", "pergunta": "Onde posso enviar sugestoes de melhorias de processos internos para a diretoria?", "resposta": "Pode encaminhar mensagens diretamente a Ouvidoria de RH, que fornece devolutiva fundamentada em ate 5 dias uteis."}, {"codigo": "SOP_OP_01", "titulo": "Envio de Encomendas e Malotes Corporativos", "categoria": "Operacoes e Logistica", "texto": "O despacho de remessas e documentos fisicos entre filiais e centralizado na equipa de expedicao. Encomendas postadas ate as 14 horas sao consolidadas para coleta da transportadora no mesmo dia util.", "pergunta": "Qual e o horario limite para entregar um pacote na expedicao para envio no proprio dia?", "resposta": "O material deve ser entregue na expedicao ate as 14h para saida no mesmo dia."}, {"codigo": "SOP_OP_02", "titulo": "Recebimento e Triagem de Mercadorias", "categoria": "Operacoes e Logistica", "texto": "Todas as caixas e volumes entregues por transportadoras devem ser conferidos fisicamente contra a nota fiscal eletrica (DANFE), verificando integridade de lacres e pesos antes da assinatura do comprovativo de entrega.", "pergunta": "O que deve ser checado antes de assinar o canhoto de entrega de uma transportadora?", "resposta": "Deve verificar a quantidade de volumes, integridade dos lacres e compatibilidade com a nota fiscal DANFE anexada."}, {"codigo": "SOP_OP_03", "titulo": "Emissao de Crachas de Acesso de Visitantes", "categoria": "Operacoes e Logistica", "texto": "A rececao emite credenciais temporarias para visitantes externos mediante apresentacao de documento oficial com foto e autorizacao do anfitriao interno, devendo o visitante ser escoltado nas areas de operacao.", "pergunta": "Quais os requisitos para liberar a entrada de um visitante nas instalacoes?", "resposta": "O visitante deve apresentar documento com fotografia, aguardar confirmacao do anfitriao e usar cracha visivel."}, {"codigo": "SOP_OP_04", "titulo": "Reserva de Salas de Reuniao e Eventos", "categoria": "Operacoes e Logistica", "texto": "Salas de reunioes e auditores devem ser agendados atraves do calendario corporativo no Outlook. Sessoes nao iniciadas apos 15 minutos do horario reservado sao liberadas automaticamente para outros setores.", "pergunta": "O que ocorre se a reuniao atrasar e a sala reservada nao for utilizada?", "resposta": "Apos 15 minutos de atraso sem utilizacao efetiva, a reserva e cancelada no sistema e a sala fica livre."}, {"codigo": "SOP_OP_05", "titulo": "Controlo de Ativos Patrimoniais e Tombamento", "categoria": "Operacoes e Logistica", "texto": "Todo o equipamento com valor superior a 500 reais recebe uma etiqueta de codigo de barras de imobilizado. A movimentacao de equipamentos entre setores deve ser atualizada no sistema de gestao de ativos.", "pergunta": "Como e feita a identificacao fisica de um computador ou monitor novo da empresa?", "resposta": "O ativo recebe uma etiqueta adesiva com codigo de patrimoniamento cadastrada no inventario do sistema."}, {"codigo": "SOP_OP_06", "titulo": "Inventario Fisico Anual de Estoque", "categoria": "Operacoes e Logistica", "texto": "O inventario geral de materiais de consumo e componentes de TI e realizado no encerramento de cada exercicio fiscal com contagem cega dupla para conciliacao contabil e identificacao de perdas.", "pergunta": "Como e garantida a acuracia do estoque de materiais no final do ano?", "resposta": "E realizado inventario fisico atraves do metodo de contagem cega dupla com reconciliacao contabil."}, {"codigo": "SOP_OP_07", "titulo": "Solicitacao de Material de Escritorio", "categoria": "Operacoes e Logistica", "texto": "Itens basicos de papelaria (papel sulfite, canetas, pastas) sao requisitados pelo representante do setor na primeira terca-feira de cada mes atraves da intranet de suprimentos.", "pergunta": "Qual e o dia designado para os setores pedirem materiais de papelaria?", "resposta": "As requisicoes mensais de suprimentos sao consolidadas na primeira terca-feira de cada mes."}, {"codigo": "SOP_OP_08", "titulo": "Uso de Veiculos da Frota Corporativa", "categoria": "Operacoes e Logistica", "texto": "A utilizacao de veiculos da empresa e restrita a viagens a servico previamente autorizadas. O condutor deve apresentar carta de conducao valida e preencher o livro de bordo com quilometragem inicial e final.", "pergunta": "Quais as exigencias para conduzir um automovel pertencente a empresa?", "resposta": "E obrigatorio possuir carta de conducao valida, ter viagem aprovada e preencher o registo de quilometragem e combustivel."}, {"codigo": "SOP_OP_09", "titulo": "Abastecimento e Prestacao de Contas de Frota", "categoria": "Operacoes e Logistica", "texto": "O abastecimento de automoveis da frota e realizado nos postos conveniados via cartao combustivel corporativo, devendo o motorista solicitar comprovante fiscal contendo a placa do automovel.", "pergunta": "Como e efetuado o pagamento do combustivel dos carros da empresa?", "resposta": "Utiliza-se o cartao combustivel da frota, exigindo a inclusao da matricula do veiculo no documento fiscal."}, {"codigo": "SOP_OP_10", "titulo": "Gestao de Residuos Reciclaveis e Descarte Verde", "categoria": "Operacoes e Logistica", "texto": "Materiais plasticos, papeis e componentes eletronicos devem ser separados nos contentores seletivos coloridos para recolha por cooperativas parceiras de reciclagem certificadas.", "pergunta": "Onde devem ser descartadas pilhas e materiais eletronicos pequenos estragados?", "resposta": "Devem ser depositados nas urnas verdes especificas de recolha de lixo eletronico nos pontos de reciclagem."}, {"codigo": "SOP_OP_11", "titulo": "Plano de Evacuacao e Brigada de Incendio", "categoria": "Operacoes e Logistica", "texto": "Ao soar o alarme sonoro de emergencia, todos os colaboradores devem evacuar o predio utilizando as escadas de emergencia em fila indiana, seguindo as orientacoes dos brigadistas para o ponto de encontro exterior.", "pergunta": "Qual o procedimento imediato ao ouvir a sirene de incendio do edificio?", "resposta": "Mantenha a calma, utilize as escadas de emergencia sem correr e dirija-se ao ponto de encontro no exterior."}, {"codigo": "SOP_OP_12", "titulo": "Armazenamento de Cargas e Procedimento de Seguranca", "categoria": "Operacoes e Logistica", "texto": "No centro de distribuicao, o uso de calcado de seguranca com biqueira de aco e colete refletivo e compulsorio. O empilhamento de pallets deve respeitar a altura maxima de 3 niveis demarcados.", "pergunta": "Quais equipamentos de protecao individual sao exigidos dentro do armazem de cargas?", "resposta": "E obrigatorio calcar sapatos de protecao com biqueira de aco e vestir colete de alta visibilidade refletivo."}, {"codigo": "SOP_OP_13", "titulo": "Transporte e Guarda de Documentos Fiscais", "categoria": "Operacoes e Logistica", "texto": "Documentos contabeis e fiscais originais devem ser arquivados em caixas padronizadas etiquetadas na sala climatizada de arquivo morto, devendo ser preservados pelo periodo decadencial de 5 anos.", "pergunta": "Quanto tempo as notas fiscais e balancetes fisicos devem ser guardados no arquivo?", "resposta": "A legislacao e as normas internas estipulam a guarda obrigatoria pelo periodo de 5 anos fiscais."}, {"codigo": "SOP_OP_14", "titulo": "Manutencao Predial e Ar-Condicionado", "categoria": "Operacoes e Logistica", "texto": "Ordens de servico para manutencao civil, hidraulica ou regulagem da temperatura do ar-condicionado devem ser encaminhadas ao setor de Facilities com 24 horas de antecedencia.", "pergunta": "A quem solicitar reparacao em caso de goteira ou falha no ar condicionado do setor?", "resposta": "Deve registar uma ordem de intervencao no setor de Facilities atraves do sistema de manutencao predial."}, {"codigo": "SOP_OP_15", "titulo": "Politica de Acesso Fora do Horario Comercial", "categoria": "Operacoes e Logistica", "texto": "A permanencia ou entrada no predio fora dos dias e horarios de expediente regular requer autorizacao previsa por e-mail do gerente da area encaminhada a seguranca patrimonial ate as 17 horas do dia util anterior.", "pergunta": "O que e necessario para trabalhar no escritorio da empresa durante um fim de semana?", "resposta": "Necessita de enviar e-mail de autorizacao da sua gerencia a portaria ate as 17h do dia util anterior."}, {"codigo": "SOP_DEV_01", "titulo": "Processo de Code Review e Pull Requests", "categoria": "Engenharia de Software e IA", "texto": "Todo o codigo submetido aos repositorios oficiais no GitHub deve passar por Pull Request aprovado por no minimo dois revisores tecnicos, alem de obter 100% de sucesso nos testes automatizados da pipeline CI/CD.", "pergunta": "Quais os criterios para um Pull Request ser integrado na branch principal?", "resposta": "Exige a aprovacao formal de pelo menos dois colegas desenvolvedores e execucao bem-sucedida de todos os testes no CI."}, {"codigo": "SOP_DEV_02", "titulo": "Gestao de Segredos e Variaveis de Ambiente", "categoria": "Engenharia de Software e IA", "texto": "E terminantemente vedado comitar chaves de API, senhas ou tokens em repositorios de codigo-fonte. Segredos devem ser injetados em tempo de execucao via ficheiros .env ignorados pelo .gitignore ou via HashiCorp Vault.", "pergunta": "Como devem ser gerenciadas as chaves de API nos projetos de desenvolvimento?", "resposta": "Nunca devem ser adicionadas ao Git; devem residir em variaveis de ambiente (.env) ou no cofre de segredos corporativo."}, {"codigo": "SOP_DEV_03", "titulo": "Padrao de Versionamento Semantico (SemVer)", "categoria": "Engenharia de Software e IA", "texto": "Os lancamentos de versoes de bibliotecas e aplicacoes internas devem seguir a convencao MAJOR.MINOR.PATCH, incrementando MAJOR para mudancas incompativeis de API, MINOR para novas funcionalidades retrocompativeis e PATCH para correcoes de bugs.", "pergunta": "Quando devemos alterar o numero de versao MAJOR de uma aplicacao interna?", "resposta": "Sempre que forem introduzidas mudancas de arquitetura ou codigo que quebrem a compatibilidade com versoes anteriores."}, {"codigo": "SOP_DEV_04", "titulo": "Padronizacao de Documentacao de APIs com OpenAPI", "categoria": "Engenharia de Software e IA", "texto": "Todas as APIs REST desenvolvidas devem disponibilizar documentacao interativa gerada a partir da especificacao OpenAPI 3.0 (Swagger), descrevendo endpoints, formatos de payload, cabecalhos e codigos de erro HTTP.", "pergunta": "Qual e o padrao adotado para documentar servicos e rotas de APIs na organizacao?", "resposta": "Deve utilizar a especificacao padrao OpenAPI 3.0 com interface visual interativa (Swagger UI)."}, {"codigo": "SOP_DEV_05", "titulo": "Estrategia de Fragmentacao Textual (Chunking) para RAG", "categoria": "Engenharia de Software e IA", "texto": "No pipeline de ingestao do OutGPT, os manuais em formato textual devem ser divididos em chunks de tamanho padrao de 500 caracteres com sobreposicao (overlap) de 50 caracteres para preservar a continuidade de sentido semantico.", "pergunta": "Qual e o tamanho de chunk e overlap definido no pipeline de RAG do OutGPT?", "resposta": "A fragmentacao textual e configurada com blocos de 500 caracteres e margem de sobreposicao de 50 caracteres."}, {"codigo": "SOP_DEV_06", "titulo": "Indexacao Vetorial com ChromaDB Local", "categoria": "Engenharia de Software e IA", "texto": "Os embeddings de texto devem ser gerados utilizando o modelo Sentence-Transformers (all-MiniLM-L6-v2) e indexados em base vetorial ChromaDB persistida localmente no disco com metadados de fonte e versao.", "pergunta": "Qual e o modelo de embeddings e o banco vetorial escolhidos para o projeto OutGPT?", "resposta": "Utiliza-se o modelo all-MiniLM-L6-v2 em conjunto com o ChromaDB local com metadados estruturados."}, {"codigo": "SOP_DEV_07", "titulo": "Modulo de Mascaramento PII e Anonimizacao", "categoria": "Engenharia de Software e IA", "texto": "Antes do envio do prompt do utilizador ao modelo de linguagem gerador, o texto deve ser analisado por um modelo de NER (Spacy ou Regex dedicado) que substitui nomes, emails e CPFs por marcadores como [EMAIL_REDACTED] e [CPF_REDACTED].", "pergunta": "Como o sistema OutGPT Enterprise impede o envio de dados pessoais para o modelo LLM?", "resposta": "O modulo de NER interceta a mensagem do utilizador substituindo dados sensiveis por etiquetas anonimas antes do envio."}, {"codigo": "SOP_DEV_08", "titulo": "Padrao de Commits Semanticos no Git", "categoria": "Engenharia de Software e IA", "texto": "As mensagens de commit devem obedecer ao padrao Conventional Commits, utilizando prefixos descritivos claros como feat para novas funcionalidades, fix para reparacao de erros, docs para documentacao e refactor para melhorias internas.", "pergunta": "Como devo escrever a mensagem de um commit que corrige um bug de interface?", "resposta": "Utilize a convencao Conventional Commits iniciando a mensagem com o prefixo 'fix: descricao da correcao efetuada'."}, {"codigo": "SOP_DEV_09", "titulo": "Metricas de Avaliacao de Recuperacao RAG", "categoria": "Engenharia de Software e IA", "texto": "A acuracia do motor de busca vetorial deve ser mensurada utilizando Precision@k, Recall@k e similaridade de cosseno, garantindo que os trechos relevantes estejam presentes entre os 3 primeiros documentos retornados.", "pergunta": "Quais metricas devem ser analisadas para saber se a busca semantica do RAG esta eficiente?", "resposta": "A analise quantitativa deve considerar a similaridade de cosseno, bem como Precision@k e Recall@k nos top-k resultados."}, {"codigo": "SOP_DEV_10", "titulo": "Metricas de Avaliacao de Geracao de Texto", "categoria": "Engenharia de Software e IA", "texto": "A coerencia e fidelidade das respostas geradas pelo assistente contra o contexto recuperado devem ser auditadas atraves das metricas BLEU, ROUGE-L e calculo de taxa de alucinacao factual em conjunto de testes padronizado.", "pergunta": "Como comprovar academicamente que o assistente nao esta gerando respostas alucinadas?", "resposta": "Comparam-se as respostas geradas com os gabaritos atraves das pontuacoes BLEU e ROUGE-L com auditoria factual."}, {"codigo": "SOP_DEV_11", "titulo": "Controle de Concorrencia e Limite de Taxa de APIs", "categoria": "Engenharia de Software e IA", "texto": "As APIs que expõem servicos de inteligencia artificial devem implementar controle de requisicoes (Rate Limiting) limitado a 60 chamadas por minuto por utilizador para prevencao de sobrecarga computacional de inferencia.", "pergunta": "O que evita que um script automatizado derrube a API do sistema OutGPT?", "resposta": "A implementacao de politicas de Rate Limiting que restringem o envio a no maximo 60 chamadas por minuto por cliente."}, {"codigo": "SOP_DEV_12", "titulo": "Arquitetura Multiplataforma da Interface Web", "categoria": "Engenharia de Software e IA", "texto": "A interface grafica do OutGPT no MVP e desenvolvida em Python Streamlit com navegacao modular em abas (Trilhas, Assistente, Documentos, Pesquisa e Sobre), facilitando a usabilidade responsiva no navegador.", "pergunta": "Quais sao as secoes principais integradas no menu de navegacao do sistema OutGPT?", "resposta": "O menu contem as secoes Inicio, Trilhas, Assistente, Documentos, Historico, Pesquisa, Resultados e Sobre."}, {"codigo": "SOP_DEV_13", "titulo": "Politica de Testes Unitarios e Integracao", "categoria": "Engenharia de Software e IA", "texto": "Todo servico de backend deve possuir cobertura minima de testes unitarios de 80% aferida via pytest e pytest-cov antes de qualquer autorizacao de merge para o branch de homologacao.", "pergunta": "Qual e a cobertura minima de testes de codigo requerida para o backend?", "resposta": "Exige-se pelo menos 80% de cobertura de codigo validada atraves da ferramenta de execucao pytest."}, {"codigo": "SOP_DEV_14", "titulo": "Procedimento de Rollback de Deploy", "categoria": "Engenharia de Software e IA", "texto": "Caso uma nova versao introduza instabilidade em producao, o procedimento de reversao (rollback) automatizado deve ser disparado no pipeline restabelecendo a imagem Docker da release anterior em menos de 5 minutos.", "pergunta": "Como agir se uma atualizacao de software falhar de forma critica em ambiente produtivo?", "resposta": "Acione a rotina automatizada de rollback no pipeline para recolocar em execucao a imagem Docker estavel anterior."}, {"codigo": "SOP_DEV_15", "titulo": "Auditoria de Prompts e Consumo de Tokens", "categoria": "Engenharia de Software e IA", "texto": "Todas as consultas enviadas ao modelo gerador sao auditadas no banco relacional SQLite local, armazenando a contagem de tokens de entrada, tokens de saida, latencia em segundos e identificador de sessao anomimo.", "pergunta": "Onde ficam guardadas as informacoes de tempo de resposta e consumo de tokens da IA?", "resposta": "Sao registradas no banco relacional SQLite local estruturado para telemetria de latencia e custos computacionais."}];
